/**
 * E2E test: creates a test customer, funds the wallet, orders a VPS
 * (same DB operations the orderServer action performs), then waits for
 * the worker to provision it and prints connection details.
 */
import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";

const db = new PrismaClient();

async function main() {
  const email = "e2e-test@nxeon.local";
  let user = await db.user.findUnique({ where: { email } });
  if (!user) {
    user = await db.user.create({
      data: {
        email,
        name: "E2E Test",
        passwordHash: await bcrypt.hash("e2e-test-password", 12),
        balanceCents: 1000,
      },
    });
  }

  const plan = await db.plan.findUnique({ where: { slug: "nano" } });
  const os = await db.osTemplate.findUnique({ where: { slug: "ubuntu-24-04" } });
  if (!plan || !os) throw new Error("seed data missing");

  const server = await db.$transaction(async (tx) => {
    await tx.user.update({ where: { id: user!.id }, data: { balanceCents: { decrement: plan.priceCents } } });
    await tx.walletTransaction.create({
      data: { userId: user!.id, amountCents: -plan.priceCents, description: "E2E order" },
    });
    // Server.hostname is globally unique (see its schema comment) — re-running
    // this script against a non-empty DB used to insert a second row literally
    // named "e2e-test" every time; now that the constraint exists, that would
    // just throw. A short random suffix per run keeps this script repeatable
    // without needing its own collision-check query.
    const hostname = `e2e-test-${Math.random().toString(36).slice(2, 8)}`;
    const s = await tx.server.create({
      data: {
        name: hostname,
        hostname,
        userId: user!.id,
        planId: plan.id,
        osTemplateId: os.id,
        expiresAt: new Date(Date.now() + 30 * 86400_000),
      },
    });
    await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
    return s;
  });

  console.log(`ordered server ${server.id}, waiting for worker...`);
  const deadline = Date.now() + 10 * 60_000;
  for (;;) {
    const s = await db.server.findUnique({ where: { id: server.id } });
    if (!s) throw new Error("server vanished");
    process.stdout.write(`  status=${s.status} vmid=${s.vmid ?? "-"}\r`);
    if (s.status === "RUNNING") {
      console.log(`\nRESULT ip=${s.ipAddress} sshPort=${s.sshPort} password=${s.rootPassword} vmid=${s.vmid}`);
      break;
    }
    if (s.status === "ERROR") {
      const job = await db.job.findFirst({ where: { serverId: s.id }, orderBy: { createdAt: "desc" } });
      throw new Error(`provisioning failed: ${job?.error}`);
    }
    if (Date.now() > deadline) throw new Error("timeout");
    await new Promise((r) => setTimeout(r, 5000));
  }
}

main().finally(() => db.$disconnect());

1	import { createHash } from "node:crypto";
2	import { SignJWT, jwtVerify, type JWTPayload } from "jose";
3	import { cookies, headers } from "next/headers";
4	import { cache } from "react";
5	import { db } from "./db";
6	import { getSettingInt } from "./settings";
7	import { clientIp, UNKNOWN_IP } from "./rate-limit";
8	import { geoLocateIp } from "./geo-ip";
9	import type { User } from "@prisma/client";
10	
11	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
12	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
13	
14	/** SHA-256 hex of a session token — the value stored in `UserSession.tokenHash`.
15	 *  Same reasoning as `ApiKey.keyHash` / `ApiToken.tokenHash`: never persist the
16	 *  bearer value itself, only a digest a stolen table can't be replayed with. */
17	function sessionTokenHash(token: string): string {
18	  return createHash("sha256").update(token).digest("hex");
19	}
20	
21	/**
22	 * The CURRENT request's own UserSession.tokenHash, or null if there is no
23	 * session cookie. Settings' "Active sessions" list is titled "Every device
24	 * currently signed in", but its empty state says "No OTHER sessions are on
25	 * record" and its bulk action is "Sign out everywhere ELSE" — the list has
26	 * always meant OTHER devices, the same distinction `revokeSession`'s sibling
27	 * action already makes deliberately (see lib/nx/account.ts:revokeOtherSessions):
28	 * "signing yourself out of the page you are standing on is not what the
29	 * control means." Exported so the page that lists sessions can exclude this
30	 * one, the same way the row would otherwise offer a "Revoke" button that
31	 * instantly signs out the tab you clicked it from, unlabeled and with no
32	 * separate confirmation from "Sign out everywhere else".
33	 */
34	export async function currentSessionTokenHash(): Promise<string | null> {
35	  const jar = await cookies();
36	  const token = jar.get(COOKIE)?.value;
37	  return token ? sessionTokenHash(token) : null;
38	}
39	
40	/**
41	 * Record (or refresh) the `UserSession` row for a session token, so "Active
42	 * sessions" in Settings shows something real and per-device revoke has a row
43	 * to act on. Best-effort and NEVER allowed to block or fail a sign-in — a geo
44	 * lookup or a write hiccup here must not be the reason a customer can't log in.
45	 */
46	async function trackSession(userId: string, token: string): Promise<void> {
47	  try {
48	    const h = await headers();
49	    const rawIp = clientIp(h);
50	    const ip = rawIp === UNKNOWN_IP ? null : rawIp;
51	    const userAgent = h.get("user-agent");
52	    const geo = geoLocateIp(ip);
53	    const location = geo ? [geo.city, geo.country].filter(Boolean).join(", ") || null : null;
54	    await db.userSession.create({
55	      data: { userId, tokenHash: sessionTokenHash(token), userAgent, ip, location },
56	    });
57	  } catch (e) {
58	    console.error("[auth] failed to record UserSession for", userId, e);
59	  }
60	}
61	
62	export async function createSession(userId: string, opts?: { revokeOtherSessions?: boolean }) {
63	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
64	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
65	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
66	  // Embed the account's current sessionVersion so a bump (password change/reset)
67	  // invalidates every previously-issued token. Missing => treated as 0.
68	  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
69	  // `typ` distinguishes this from the impersonation token below. Both are signed
70	  // with the SAME secret, so without it the two are interchangeable strings —
71	  // see the note on `assertSessionToken`.
72	  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0, typ: "session" })
73	    .setProtectedHeader({ alg: "HS256" })
74	    .setIssuedAt()
75	    .setExpirationTime(`${days}d`)
76	    .sign(secret);
77	  const jar = await cookies();
78	  // Secure in production regardless of COOKIE_SECURE, matching the impersonation
79	  // cookie — a deploy that forgets COOKIE_SECURE=1 must not ship a non-Secure
80	  // session cookie. Local http dev stays non-secure (NODE_ENV !== "production").
81	  const secure = process.env.NODE_ENV === "production";
82	  jar.set(COOKIE, token, {
83	    httpOnly: true,
84	    sameSite: "lax",
85	    secure,
86	    maxAge: 60 * 60 * 24 * days,
87	    path: "/",
88	  });
89	  // Non-sensitive, JS-readable flag so the (static) marketing header can show
90	  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
91	  // no identity — just presence. Always cleared alongside the session cookie.
92	  jar.set("nxeon_authed", "1", {
93	    httpOnly: false,
94	    sameSite: "lax",
95	    secure,
96	    maxAge: 60 * 60 * 24 * days,
97	    path: "/",
98	  });
99	  // `opts.revokeOtherSessions` mirrors the sessionVersion bump above at the
100	  // UserSession layer: changePassword and signOutOtherSessions both invalidate
101	  // every OTHER outstanding token via sessionVersion, then call createSession to
102	  // re-issue one for the caller's own device. Without this, the rows those older
103	  // tokens were tracked under (if any) would keep showing as "active" in
104	  // Settings even though sessionVersion has already made them unusable.
105	  if (opts?.revokeOtherSessions) {
106	    await db.userSession
107	      .updateMany({ where: { userId, revokedAt: null }, data: { revokedAt: new Date() } })
108	      .catch(() => {});
109	  }
110	  await trackSession(userId, token);
111	}
112	
113	export async function destroySession() {
114	  const jar = await cookies();
115	  jar.delete(COOKIE);
116	  jar.delete("nxeon_authed");
117	}
118	
119	/**
120	 * Is this payload allowed to act as a SESSION, as opposed to an impersonation
121	 * grant?
122	 *
123	 * Both cookies are HS256 over the same `AUTH_SECRET`, so as far as `jwtVerify`
124	 * is concerned an impersonation token is a perfectly valid session token — the
125	 * only difference was which claims happened to be present, and nothing checked.
126	 * Moving the value of `nxeon_session_imp` into `nxeon_session` therefore
127	 * produced a REAL session as the impersonated customer: not flagged as
128	 * impersonation, so `impersonating()` returns null, the banner does not render,
129	 * and `audit()` in lib/actions.ts stops appending `actingAdmin=…` — every
130	 * subsequent action is recorded as the customer's own. For a platform holding
131	 * customer servers and saved cards, "an admin can act as a customer with no
132	 * trace" is the accountability failure that matters even though the admin was
133	 * already privileged.
134	 *
135	 * An impersonation grant is also the weaker credential by design (2h, no
136	 * `sessionVersion`), so it must not be promotable into the stronger one: it
137	 * carries no `sv`, which `realUser` reads as 0, and 0 is the DEFAULT
138	 * sessionVersion — so for any account that has never changed its password the
139	 * promotion also survives every existing revocation check.
140	 *
141	 * Old session tokens minted before `typ` existed carry neither claim and stay
142	 * valid, so nobody is signed out by this.
143	 */
144	function assertSessionToken(payload: JWTPayload): boolean {
145	  if (payload.adminId !== undefined) return false;
146	  return payload.typ === undefined || payload.typ === "session";
147	}
148	
149	/**
150	 * Lightweight "is there a valid session?" check — verifies the session JWT
151	 * (signature + expiry) WITHOUT a DB round-trip. Used by /api/auth/status so the
152	 * (static) marketing header can authoritatively show "Back to portal" even when
153	 * the non-httpOnly `nxeon_authed` flag cookie is missing or stale.
154	 *
155	 * KNOWN AND ACCEPTED LIMIT: with no DB round-trip this cannot see a
156	 * `sessionVersion` bump or a suspension, so for a revoked session it can still
157	 * answer `true`. That is deliberate — this endpoint is hit by the marketing
158	 * header on every page view, and it decides nothing but which of two links to
159	 * draw. Every route that actually grants access goes through `realUser`, which
160	 * does check both. Do not reach for this function to authorise anything.
161	 */
162	export async function isSignedIn(): Promise<boolean> {
163	  const jar = await cookies();
164	  const token = jar.get(COOKIE)?.value;
165	  if (!token) return false;
166	  try {
167	    const { payload } = await jwtVerify(token, secret);
168	    return assertSessionToken(payload);
169	  } catch {
170	    return false;
171	  }
172	}
173	
174	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
175	
176	/** The real signed-in account, ignoring any impersonation. */
177	export const realUser = cache(async (): Promise<User | null> => {
178	  const jar = await cookies();
179	  const token = jar.get(COOKIE)?.value;
180	  if (!token) return null;
181	  try {
182	    const { payload } = await jwtVerify(token, secret);
183	    if (!payload.sub) return null;
184	    // An impersonation grant is not a session (see assertSessionToken).
185	    if (!assertSessionToken(payload)) return null;
186	    const user = await db.user.findUnique({ where: { id: payload.sub } });
187	    if (!user || user.suspended) return null;
188	    // Session revocation: a token is only valid while its embedded version matches
189	    // the account's current sessionVersion. Older tokens without `sv` count as 0,
190	    // so accounts that never bumped stay logged in (backward-compatible).
191	    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
192	    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
193	    // Per-device revocation: Settings' "Revoke" on one listed session sets that
194	    // ROW's revokedAt (lib/nx/account.ts:revokeSession) without touching
195	    // sessionVersion, so the check above alone would not see it. Look the token
196	    // up by its own hash and refuse it if that specific row says revoked.
197	    //
198	    // NO MATCHING ROW is treated as valid, deliberately — same call the codebase
199	    // already makes for tokens minted before `typ` existed (see the docblock on
200	    // `assertSessionToken`): a session from before this tracking existed, or from
201	    // a path that predates it, must not be mass-logged-out by a change that adds
202	    // bookkeeping. It simply isn't individually revocable until its owner logs in
203	    // again and gets a tracked row — the sessionVersion-based "sign out
204	    // everywhere" control above still reaches it regardless.
205	    const tokenHash = sessionTokenHash(token);
206	    const tracked = await db.userSession.findUnique({
207	      where: { tokenHash },
208	      select: { id: true, revokedAt: true, lastSeenAt: true },
209	    });
210	    if (tracked?.revokedAt) return null;
211	    if (tracked) {
212	      // Best-effort activity stamp — never block the request on this write, and
213	      // only bother once a minute per session rather than on every render.
214	      if (Date.now() - tracked.lastSeenAt.getTime() > 60_000) {
215	        db.userSession
216	          .update({ where: { id: tracked.id }, data: { lastSeenAt: new Date() } })
217	          .catch(() => {});
218	      }
219	    }
220	    return user;
221	  } catch {
222	    return null;
223	  }
224	});
