226	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
227	export const currentUser = cache(async (): Promise<User | null> => {
228	  const real = await realUser();
229	  if (!real) return null;
230	  if (real.role === "ADMIN") {
231	    const jar = await cookies();
232	    const imp = jar.get(IMP_COOKIE)?.value;
233	    if (imp) {
234	      try {
235	        const { payload } = await jwtVerify(imp, secret);
236	        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
237	          const target = await db.user.findUnique({ where: { id: payload.sub } });
238	          // The token outlives the checks `impersonateUser` made when it minted
239	          // it (2h), so they are re-made here against the CURRENT row rather
240	          // than trusted from the past:
241	          //
242	          //  - suspended: `realUser` refuses to hand out a session for a
243	          //    suspended account, and impersonation must not be a side door that
244	          //    resurrects one. Reviewing a suspended abuser's account is a
245	          //    read-only job; it must not come with the ability to act as them.
246	          //  - ADMIN: refused at mint time, but a customer promoted DURING an
247	          //    open impersonation would otherwise turn the impersonator's
248	          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
249	          //    `currentUser`, so admin actions would run attributed to the
250	          //    promoted account instead of the person taking them. The rule that
251	          //    admins refuse to act while impersonating depends on this.
252	          //
253	          // Falling through to the real admin is the safe failure: they are
254	          // simply themselves again, which is visible on screen.
255	          if (target && !target.suspended && target.role !== "ADMIN") return target;
256	        }
257	      } catch {
258	        /* expired/invalid impersonation — fall through to real user */
259	      }
260	    }
261	  }
262	  return real;
263	});
