265	/** Non-null when the current request is an admin impersonating a customer. */
266	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
267	  const real = await realUser();
268	  if (!real || real.role !== "ADMIN") return null;
269	  const target = await currentUser();
270	  if (!target || target.id === real.id) return null;
271	  return { admin: real, target };
272	});
273	
274	export async function setImpersonation(targetUserId: string) {
275	  const real = await realUser();
276	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
277	  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
278	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
279	    .setProtectedHeader({ alg: "HS256" })
280	    .setIssuedAt()
281	    .setExpirationTime("2h")
282	    .sign(secret);
283	  const jar = await cookies();
284	  jar.set(IMP_COOKIE, token, {
285	    httpOnly: true,
